SELECT 
    ROUND(100.0 * SUM(CASE WHEN payment_type = 'Credit card' THEN 1 ELSE 0 END) / COUNT(*), 4) AS credit_card_percentage
FROM fct_trips;

SELECT 
    ROUND(100.0 * SUM(CASE WHEN pickup_borough = 'Manhattan' THEN 1 ELSE 0 END) / COUNT(*), 4) AS manhattan_trip_percentage
FROM fct_trips;

SELECT 
    100.0 * SUM(CASE WHEN pickup_zone IN ('JFK Airport', 'LaGuardia Airport') THEN total_amount ELSE 0 END) / SUM(total_amount) AS percentage_revenue
FROM fct_trips;

SELECT 
    ROUND(100.0 * SUM(CASE WHEN is_weekend THEN 1 ELSE 0 END) / COUNT(*), 4) AS weekend_trip_percentage
FROM fct_trips;

SELECT 
    ROUND(
        SUM(CASE WHEN pickup_date < '2023-07-01' THEN total_amount ELSE 0 END) * 100.0 / SUM(total_amount),
        2
    ) AS percentage_revenue_jan_to_jun
FROM fct_trips;

SELECT 
    (SELECT AVG(fare_amount) FROM fct_trips WHERE month_key = '2023-12') - 
    (SELECT AVG(fare_amount) FROM fct_trips WHERE month_key = '2023-01') AS fare_difference;

SELECT AVG(daily_trips) AS avg_daily_trips
FROM (
    SELECT pickup_date, COUNT(*) AS daily_trips
    FROM fct_trips
    GROUP BY pickup_date
) t;

SELECT AVG(daily_revenue) AS avg_daily_revenue
FROM (
  SELECT pickup_date, SUM(total_amount) AS daily_revenue
  FROM fct_trips
  GROUP BY pickup_date
) sub;

SELECT MEDIAN(trip_count) AS median_trips_per_day
FROM (
  SELECT pickup_date, COUNT(*) AS trip_count
  FROM fct_trips
  GROUP BY pickup_date
);

